/* ---- style-9-integration.css ---- */
/* ===== integration: two-row crest on text-lifted screens (1440/1280-class, --tx >= 1.15) =====
   The index grid leaves the crowded first row and runs as one 6-cell row under it; the plume top (G.T0)
   moves down by CREST2_DY so nothing overlaps. 1920 is untouched. */
#stage.crest2 #crest{height:148px}
#stage.crest2 #crest .igrid{left:24px;top:100px;grid-template-columns:repeat(6,max-content);grid-auto-rows:auto;gap:0 6px}
#stage.crest2 #crest .igrid .ic{padding:4px 8px 4px 7px}
#stage.crest2 #crest .clock{left:500px;top:40px}
#stage.crest2 #crest .nifty{left:214px}
/* inspector: the pick-rule row may wrap (sector-cap names) */
#inspector .row.note,#stack .sheet .row.note{white-space:normal;align-items:flex-start}
#inspector .row.note>span:last-child,#stack .sheet .row.note>span:last-child{text-align:right;font-family:var(--f-ui);font-size:.92em;letter-spacing:.02em;color:var(--ink-2);line-height:1.25}
#inspector .g2,#stack .sheet .g2{display:flex;flex-wrap:wrap;overflow:hidden;margin:0 calc(-7px*var(--tx))}
#inspector .g2>.row,#stack .sheet .g2>.row{flex:1 0 50%;min-width:max-content;box-sizing:border-box;margin:0 0 0 -1px;padding:calc(4px*var(--tx)) calc(7px*var(--tx)) 0;border-left:1px solid rgba(154,168,189,.12)}
#stack .sheet .g2{margin:0 -8px} #stack .sheet .g2>.row{padding:5px 8px 0}
#inspector .g2>.row.note,#stack .sheet .g2>.row.note{min-width:0}
#inspector .g2>.row.full,#stack .sheet .g2>.row.full{flex-basis:100%}
.bridge{pointer-events:auto;cursor:pointer}
/* ================= stacked (phone / portrait) layout: the vertical pipeline =================
   Injected by tools/patch_terminal.py at the end of the page's main <style> (after 02.html's own rules, so it wins);
   the light layer (tools/terminal_light.html) is appended after it. Everything is scoped to html.stacked / #stack, so
   the desktop stage and the Home peek frame (never stacked) are untouched. Text floor: 10px real. */

/* the page scrolls: html must not keep overflow:hidden (it goes to the viewport and nothing would scroll) */
html.stacked{height:auto;overflow:visible;overscroll-behavior-y:contain;-webkit-text-size-adjust:100%;text-size-adjust:100%;overflow-anchor:none}
html.stacked body.stacked{height:auto;min-height:100%;overflow-anchor:none}
body.stacked #stack{max-width:none;margin:0;padding:0;-webkit-touch-callout:none;-webkit-tap-highlight-color:transparent;-webkit-user-select:none;user-select:none}
#stack button{font:inherit;color:inherit;margin:0;-webkit-appearance:none;appearance:none;-webkit-tap-highlight-color:transparent}
#stack button:focus{outline:none}
#stack button:focus-visible{outline:2px solid rgba(169,184,255,.8);outline-offset:1px}

/* ---------- station nav (sticky) ---------- */
#stack .phnav{position:sticky;top:0;z-index:40;height:44px;background:rgba(10,15,23,.82);-webkit-backdrop-filter:blur(12px) saturate(1.4);backdrop-filter:blur(12px) saturate(1.4);border-bottom:1px solid var(--hair)}
#stack .phnavin{position:relative;max-width:760px;height:100%;margin:0 auto;display:flex;align-items:stretch;padding:0 4px 0 12px;box-sizing:border-box}
#stack .phn{position:relative;flex:1 1 0;min-width:44px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;padding:0 2px;background:none;border:0;color:var(--ink-3);cursor:pointer;transition:color .2s}
#stack .phn .c{display:flex;align-items:center;gap:3px;font:700 10px/1 var(--f-ui);letter-spacing:.1em;white-space:nowrap}
#stack .phn .n{font:600 12.5px/1 var(--f-num);font-variant-numeric:tabular-nums;color:var(--ink-2);letter-spacing:.01em}
#stack .phn .tri{width:7px;height:7px;fill:currentColor;flex:none}
#stack .phn.up .tri,#stack .phn.up .n{color:var(--bull)}
#stack .phn.dn .tri,#stack .phn.dn .n{color:var(--bear)}
#stack .phn .bd{display:flex;gap:1px;width:34px;height:3px;border-radius:2px;overflow:hidden}
#stack .phn .bd i{display:block;height:100%;flex:1}
#stack .phn .bd .b{background:var(--bull)} #stack .phn .bd .r{background:var(--bear)}
#stack .phn::after{content:"";position:absolute;left:22%;right:22%;bottom:0;height:2px;border-radius:2px 2px 0 0;background:var(--ink-2);opacity:0;transform:scaleX(.3);transition:opacity .2s,transform .28s var(--ease)}
#stack .phn.up::after{background:var(--bull)} #stack .phn.dn::after{background:var(--bear)}
#stack .phn.on{color:var(--ink)}
#stack .phn.on::after{opacity:1;transform:none}
#stack .phn.find{flex:0 0 44px}
#stack .phn.find svg{width:19px;height:19px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round}
#stack .phprog{position:absolute;left:0;right:0;bottom:-1px;height:1px;background:linear-gradient(90deg,rgba(169,184,255,0),rgba(169,184,255,.22) 30%,rgba(169,184,255,.22) 70%,rgba(169,184,255,0));pointer-events:none}
#stack .phprog i{position:absolute;left:0;top:-1.5px;width:8px;height:4px;border-radius:2px;background:#fff;box-shadow:0 0 6px rgba(169,184,255,.9);will-change:transform}

/* ---------- page, rebuild holder, sections ---------- */
#stack .phpage{position:relative;max-width:760px;margin:0 auto;padding:0 12px 0 26px;box-sizing:border-box}
#stack .phnext{position:relative;height:0;overflow:hidden;visibility:hidden;pointer-events:none}
#stack .phbody{position:relative;padding-top:12px}
#stack .phsec{position:relative;margin:0 0 22px}
#stack .phhd{display:flex;align-items:center;gap:8px;height:26px;margin:0 0 8px;white-space:nowrap}
#stack .phhd b{display:flex;align-items:center;gap:5px;font:800 11px/1 var(--f-ui);letter-spacing:.16em;color:var(--ink)}
#stack .phhd span{font:600 10px/1 var(--f-ui);letter-spacing:.1em;color:var(--ink-3);overflow:hidden;text-overflow:ellipsis}
#stack .phhd::after{content:"";flex:1 1 12px;min-width:12px;height:1px;background:linear-gradient(90deg,var(--hair),rgba(26,36,51,0))}
#stack .phhd .tri{width:8px;height:8px;fill:currentColor}
#stack .phhd.up b{color:var(--bull-hi)} #stack .phhd.dn b{color:var(--bear-hi)}
#stack .phhd.set{margin-top:18px}
#stack .phhd .ev{color:var(--amber)}

/* ---------- spine, station nodes, count badges ---------- */
#stack .phspine{position:absolute;left:-14px;width:2px;bottom:auto;overflow:visible;pointer-events:none;z-index:1;
  background:linear-gradient(180deg,rgba(232,241,255,.2) 0%,rgba(232,241,255,.45) calc(var(--s1,40%) - 12%),rgba(232,241,255,.95) var(--s1,40%),rgba(232,241,255,.55) var(--s2,55%),rgba(232,241,255,.5) calc(var(--s3,85%) - 8%),rgba(232,241,255,.95) var(--s3,85%),rgba(232,241,255,.75) 100%);
  box-shadow:0 0 8px rgba(169,184,255,.45)}
#stack .phnode{position:absolute;left:-13px;z-index:2;width:9px;height:9px}
#stack .phnode.dia{width:7px;height:7px}
#stack .phnode.beacon{width:7px;height:7px}
#stack .phnode.set{width:11px;height:11px}
#stack .phnode .ring{width:7px;height:7px}
#stack .phcnt{position:absolute;width:auto;height:auto;padding:0;margin:0;border:0;background:none;pointer-events:auto;cursor:pointer;z-index:5;transform:none}
#stack .phcnt b{position:relative;left:auto;top:auto;right:auto;bottom:auto;display:block;transform:none}
#stack .phcnt::after{content:"";position:absolute;left:50%;top:50%;width:max(100%,40px);height:max(100%,40px);transform:translate(-50%,-50%)}
#stack .phncnt{left:-13px;transform:translateX(-50%)}
#stack .phcap{position:absolute;width:auto;height:auto;pointer-events:none;z-index:4}
#stack .phcap b{position:relative;left:auto;top:auto;right:auto;bottom:auto;display:block}
#stack.brush .phspine,#stack.brush .phnode{opacity:.4}

/* ---------- MARKET: crest, the six setups, sectors ---------- */
#stack .phcrest{position:relative;margin:0 0 16px;touch-action:pan-y;cursor:crosshair}
#stack .pulse .pcount .k{font-size:10px;letter-spacing:.12em}
#stack .pulse .ptag{cursor:pointer}
#stack .pulse .ptag .k{font-size:10px;letter-spacing:.1em}
#stack .pulse .ptag b{font-size:13px}
#stack .pulse .ptag .v{font-size:11px}
#stack .phrail{margin:0 0 18px}
#stack .phrailhd{display:flex;align-items:center;gap:6px;height:40px;margin:0 0 6px;white-space:nowrap}
#stack .phreact{position:relative!important;width:40px;height:40px;flex:none;margin-left:-6px}
#stack .phreact>*{margin:20px 0 0 20px}
#stack .phrailhd .phcnt{position:relative}
#stack .phrailhd .k{font:800 11px/1 var(--f-ui);letter-spacing:.16em;color:var(--ink);margin-left:4px}
#stack .phrailhd .sub{margin-left:auto;font:600 10px/1 var(--f-ui);letter-spacing:.06em;color:var(--ink-3);overflow:hidden;text-overflow:ellipsis}
#stack .phrailg{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}
#stack .phbody.wide:not(.r3) .phrailg{grid-template-columns:repeat(6,minmax(0,1fr))}   /* short frames under 700: the rail stays 3-across */
#stack .phpick{position:relative;display:flex;align-items:center;gap:7px;height:48px;min-width:0;padding:0 8px 0 7px;border-radius:8px;text-align:left;cursor:pointer;overflow:hidden;
  border:1px solid rgba(var(--sc),.38);background:linear-gradient(135deg,rgba(var(--sc),.17),rgba(var(--sc),.04) 72%),var(--panel);transition:opacity .14s,box-shadow .14s}
#stack .phpick .mg{position:relative;width:26px;height:26px;flex:none;border-radius:6px;display:flex;align-items:center;justify-content:center;font:700 12px/1 var(--f-tk);color:#fff;
  background:linear-gradient(135deg,rgba(var(--sc),.5),rgba(10,15,23,.92) 85%);border:1px solid rgba(var(--sc),.5);overflow:hidden}
#stack .phpick .tw{display:flex;flex-direction:column;gap:4px;min-width:0}
#stack .phpick .tk{display:block;font:700 15px/1 var(--f-tk);letter-spacing:.01em;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#stack .phpick .ln{display:flex;align-items:baseline;gap:5px;white-space:nowrap}
#stack .phpick .pc{font:600 11px/1 var(--f-num);font-variant-numeric:tabular-nums;color:rgb(var(--hi));letter-spacing:-.01em}
#stack .phpick .rk{font:700 10px/1 var(--f-num);color:var(--ink-3)}
#stack .phpick.lit{box-shadow:0 0 0 1px rgba(232,241,255,.7)}
#stack .phsecs .phsub{display:flex;align-items:baseline;gap:6px;margin:0 0 8px;font:700 10px/1 var(--f-ui);letter-spacing:.14em;color:var(--ink-3)}
#stack .phsecs .phsub b{font-weight:800;color:var(--ink-2)}
