/* ================= phone motion (SPEC §7): the build show's pre states, the ambient layer =================
   Injected by tools/patch_terminal.py after tools/terminal_phone.css (still inside the main <style>, ahead of the light
   layer). A section that has not played its intro carries class phpre on the intro's own element; everything here is
   scoped to it or to #stack, so a rebuild with nothing left to play renders final and the desktop never sees it. */

/* the pre states land at once; CSS loops pause in sections that are off screen */
#stack .phnoanim,#stack .phnoanim *{transition:none!important}
#stack .phoff,#stack .phoff *,#stack .phoff::before,#stack .phoff::after,#stack .phoff *::before,#stack .phoff *::after{animation-play-state:paused!important}
/* the desktop's CSS loops, compositor-only on the phone (transform / opacity; same size, timing and colour):
   the beacon ring and the crest's zero ring scale instead of growing width / height; the card specular sweeps with
   translateX instead of left; the sheen's conic light turns on its own ::before (rotate) instead of animating --ang;
   the reactor's rings turn as two <svg> boxes (split in phFxSplitReactor) instead of SVG <g> transforms */
#stack .beacon .ring{width:80px;height:80px;border-width:2.4px;pointer-events:none;animation-name:phring}
@keyframes phring{0%{transform:translate(-50%,-50%) scale(.075);opacity:.9}35%,100%{transform:translate(-50%,-50%) scale(1);opacity:0}}
#stack .pulse .pz::after{width:30px;height:30px;border-width:1.5px;animation-name:phpzr}
@keyframes phpzr{0%{transform:translate(-50%,-50%) scale(.2);opacity:.9}60%,100%{transform:translate(-50%,-50%) scale(1);opacity:0}}
#stack .ticket .spec::before{left:-140px;animation-name:phspecs}
@keyframes phspecs{0%{transform:translateX(0) skewX(-18deg)}14%,100%{transform:translateX(780px) skewX(-18deg)}}
#stack .ticket .sheen{background:none;animation:none;overflow:hidden}
#stack .ticket .sheen::before{content:"";position:absolute;left:50%;top:50%;width:180%;aspect-ratio:1;margin:-90% 0 0 -90%;pointer-events:none;
  background:conic-gradient(transparent 0 60%,rgba(255,255,255,.9) 70%,rgba(var(--hot),.9) 75%,transparent 85%);animation:phang 8s linear infinite}
@keyframes phang{to{transform:rotate(360deg)}}
#stack .reactor svg g.r1,#stack .reactor svg g.r2{animation:none}
#stack .reactor svg.phr1{animation:spin 24s linear infinite}
#stack .reactor svg.phr2{animation:spin 36s linear infinite reverse}
/* no entrance, glow ring or flare may ever widen the page (a phone would shrink the whole page to fit it) */
#stack .phpage{overflow-x:clip}

/* spine nodes and their count badges wait for their station */
#stack .phwait,#stack.brush .phwait{opacity:0}

/* ---------- MARKET: the setup chips pop, the sectors light in order ---------- */
#stack .phpre .phreact,#stack .phpre .phrailhd .phcnt{transition:opacity .3s var(--ease),transform .5s cubic-bezier(.2,1.5,.35,1)}
#stack .phpre .phreact:not(.in){opacity:0;transform:scale(.4)}
